head.script:
scwin.init = function() {
    var jsonData = [{
        "col1": "col1",
        "col2": "col2",
        "col3": "col3",
        "col4": "col4",
        "col5": "col5",
        "col6": "col6",
        "col7": "col7",
        "col8": "col8",
        "col9": "col9",
        "col10": "col10"
    }];
    dataList1.setJSON(jsonData);
};
scwin.trigger1_onclick = function(e) {
    grd1.setColumnOrder(["col2", "col1", "col7", "col8"]);
};
scwin.trigger2_onclick = function(e) {
    console.log("grd1.getColumnVisible('col1') :: " + grd1.getColumnVisible('col1'));
    console.log("grd1.getColumnVisible('col2') :: " + grd1.getColumnVisible('col2'));
    console.log("grd1.getColumnVisible('col3') :: " + grd1.getColumnVisible('col3'));
    console.log("grd1.getColumnVisible('col4') :: " + grd1.getColumnVisible('col4'));
    console.log("grd1.getColumnVisible('col5') :: " + grd1.getColumnVisible('col5'));
    console.log("grd1.getColumnVisible('col6') :: " + grd1.getColumnVisible('col6'));
    console.log("grd1.getColumnVisible('col7') :: " + grd1.getColumnVisible('col7'));
    console.log("grd1.getColumnVisible('col8') :: " + grd1.getColumnVisible('col8'));
    console.log("grd1.getColumnVisible('col9') :: " + grd1.getColumnVisible('col9'));
    console.log("grd1.getColumnVisible('col10') :: " + grd1.getColumnVisible('col10'));
    console.log("grd1.getHeaderColumnVisible('h_col1') :: " + grd1.getHeaderColumnVisible('h_col1'));
    console.log("grd1.getHeaderColumnVisible('h_col2') :: " + grd1.getHeaderColumnVisible('h_col2'));
    console.log("grd1.getHeaderColumnVisible('h_col3') :: " + grd1.getHeaderColumnVisible('h_col3'));
    console.log("grd1.getHeaderColumnVisible('h_col4') :: " + grd1.getHeaderColumnVisible('h_col4'));
    console.log("grd1.getHeaderColumnVisible('h_col5') :: " + grd1.getHeaderColumnVisible('h_col5'));
    console.log("grd1.getHeaderColumnVisible('h_col6') :: " + grd1.getHeaderColumnVisible('h_col6'));
    console.log("WebSquare.wUnit.getObjById('grd1').getHeaderColumnVisible('h_col7') :: " + grd1.getHeaderColumnVisible('h_col7'));
};
scwin.trigger3_onclick = function(e) {
    grd1.setColumnVisible('col2', false);
    //		grd1.setColumnVisible('col7', false);
};
scwin.trigger4_onclick = function(e) {
    var options = {
        fileName: "test.xlsx",
        columnMove: "true",
        autoSizeColumn: "true"
    };
    grd1.advancedExcelDownload(options);
};
scwin.isBetween = function(colVal, idBefore, idAfter) {
    var dataValue = WebSquare.util.getDataPrefix("value");
    var el = WebSquare.wUnit.getDomById($p.id + idBefore).nextElementSibling;
    var nextElId = WebSquare.wUnit.getDomById($p.id + el.getAttribute("id")).nextElementSibling.getAttribute('id');
    return el.getAttribute(dataValue) == colVal && nextElId == idAfter;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일을 실행 및 콘솔 실행 후 'moveCol'버튼을 클릭한다.
    //1. Run the sample file and run the console and click the 'moveCol' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    // verify step 1. h_col1의 row가 h_col2와 h_col5사이로 이동되어진다.
    //1. The row of h_col1 is moved between h_col2 and h_col5.
    WebSquare.wUnit.addCommand("assert", "scwin.isBetween('h_col1', $p.id+'grd1_h_col2',$p.id+'grd1_h_col5')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 2. 'hidden'버튼을 클릭한다.
    //2. Click the 'hidden' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    // verify step 2. h_col2d의 row가 숨겨져서 보여진다.
    //2. The row of h_col2d is shown hidden.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd1').getColumnVisible('col2')", "false");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 3. 'chkVisible'을 클릭하고 콘솔창을 확인한다.
    //3. Click 'chkVisible' and check the console window.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    // verify step 3. body의 col2, col5, col6 값은 false로 보여지고 col3, col10은 undefined로 보여지고 나머지는 true로 보여진다.그리고 header의 col2, col3, col4 값은 false로 보여진다.
    //3. The col2, col5, and col6 values in the body are shown as false, and col3 and col10 are shown as undefined and the rest are shown as true.The col2, col3, and col4 values in the header are shown as false.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd1').getColumnVisible('col2')", "false");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd1').getColumnVisible('col5')", "false");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd1').getColumnVisible('col6')", "false");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd1').getColumnVisible('col3') == undefined", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd1').getColumnVisible('col10') == undefined", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd1').getColumnVisible('col4')", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd1').getColumnVisible('col7')", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd1').getColumnVisible('col8')", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd1').getColumnVisible('col9')", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd1').getColumnVisible('col1')", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd1').getHeaderColumnVisible('h_col2')", "false");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd1').getHeaderColumnVisible('h_col2')", "false");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd1').getHeaderColumnVisible('h_col2')", "false");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
    //Function unitTest
    //Created By: Sang.do
    //Created By: 26-Jan-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
